import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val c = Array(3) { Array(4) { ' ' } }

    for (i in 0 until 3) {
        // Read a line, if empty read next. scanf("%c") reads whitespace, so we handle input carefully.
        // Assuming input is provided as 3 lines of 4 chars each, or continuous stream.
        // To mimic scanf("%c") exactly reading 12 chars including newlines is tricky with Scanner line based.
        // Common competitive programming interpretation: 3 lines of strings.
        val line = if (scanner.hasNextLine()) scanner.nextLine() else ""
        // If line is empty (due to previous newline), read again? 
        // Simpler: read tokens or just assume 3 lines.
        // Let's read 4 characters per row.
        var idx = 0
        while (idx < 4) {
            if (line.length > idx) {
                c[i][idx] = line[idx]
                idx++
            } else if (scanner.hasNext()) {
                // If line too short, read next token/line? 
                // scanf("%c") reads exactly one char. 
                // Best effort: read next line and continue.
                val nextLine = scanner.nextLine()
                for (ch in nextLine) {
                    if (idx < 4) c[i][idx++] = ch
                }
            } else {
                break
            }
        }
    }

    val cond1 = c[0][0] == c[2][2]
    val cond2 = c[0][1] == c[2][1]
    val cond3 = c[0][2] == c[2][0]
    val cond4 = c[1][0] == c[1][2]
    val cond5 = c[1][1] == c[1][1] // Always true
    val cond6 = c[1][2] == c[1][0] // Redundant with cond4

    if (cond1 && cond2 && cond3 && cond4 && cond5 && cond6) {
        println("YES")
    } else {
        println("NO")
    }
}

